#include <iostream>
using namespace std;
int main() {
    int a, b;
    char op;
    cout << "Enter two integers: ";
    cin >> a >> b;
    cout << "Enter an operator (+, -, *, /): ";
    cin >> op;
    switch (op) {
        case '+': cout << a << " + " << b << " = " << a + b << endl; break;
        case '-': cout << a << " - " << b << " = " << a - b << endl; break;
        case '*': cout << a << " * " << b << " = " << a * b << endl; break;
        case '/':
            if (b != 0) cout << a << " / " << b << " = " << (float)a / b << endl;
            else cout << "Division by zero is not allowed." << endl;
            break;
        default: cout << "Invalid operator!" << endl;
    }
    return 0;
}

