#include <iostream>
using namespace std;
int main() {
    int nValue, i = 1, sum = 0;
    cout << "Enter nValue: ";
    cin >> nValue;
    while (i <= nValue) {
        sum = sum + i;
        i++;
    }
    cout << "Sum = " << sum << endl;
    return 0;
}

